const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:5180/contracts');
  await page.waitForSelector('text=Vendor Agreement — Castellan Freight');
  await page.click('text=Vendor Agreement — Castellan Freight');
  await page.waitForSelector('text=You do not have access to this contract');
  await page.screenshot({ path: '/tmp/actual-access-denied.png' });
  await browser.close();
})();
EOF
